def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([2]), fmt([1, 1, 1]), fmt([36]), fmt([1, 6, 7, 12, 36]), fmt([100, 97, 49]), fmt([10**8]),
             fmt([99999989]), fmt([4, 9, 16, 25, 64])]
    for n in (3, 5, 8, 12, 20):
        for _ in range(2):
            tests.append(fmt([rng.randint(1, 3000) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**8) for _ in range(30)]))
    # large primes: worst case for sqrt loop
    primes = [99999989, 99999971, 99999959, 99999941, 99999931, 99999847, 99999839, 99999827]
    tests.append(fmt([primes[i % len(primes)] for i in range(1000)]))
    tests.append(fmt([10**8 - rng.randint(0, 5000) for _ in range(1000)]))
    tests.append(fmt([rng.randint(9 * 10**7, 10**8) for _ in range(1000)]))
    tests.append(fmt([(9999 - i) ** 2 for i in range(1000)]))
    return tests
